NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Lamentations'

CHAPTERS = {
    1: {
        1: 'Kuinka istuukaan yksinään tuo runsasväkinen kaupunki! Kuinka onkaan tullut lesken kaltaiseksi se, joka oli suuri kansakuntien joukossa! Ruhtinatar maakuntien joukossa on tullut pakkotyön alaiseksi.',
        2: 'Se itkee katkerasti yössä, ja sillä on kyyneleet poskillaan. Sillä ei ole lohduttajaa kaikkien niiden joukossa, jotka sitä rakastivat. Uskottomia ovat sille olleet kaikki sen ystävät, ja he ovat tulleet sen vihamiehiksi.',
        3: 'Juuda on mennyt vankeuteen kurjuudesta ja työn kovuudesta. Se istuu pakanakansojen joukossa eikä löydä lepoa. Kaikki sen vainoajat saavuttivat sen, kun se oli ahdistusten keskellä.',
        4: 'Siionin tiet surevat, sillä juhlille ei ole tulijoita. Kaikki sen portit ovat autioina, sen papit huokailevat, sen neitsyet ovat murheissaan, ja sillä itsellään on katkera mieli.',
        5: 'Sen vastustajat ovat sen päällikköinä, ja sen viholliset menestyvät. Sillä Herra on saattanut sen murheelliseksi sen rikosten paljouden tähden. Sen pienet lapset ovat menneet vankeuteen vihollisen vieminä.',
        6: 'Mennyt on tytär Siionilta kaikki hänen kauneutensa. Hänen ruhtinaansa ovat kuin peurat, jotka eivät löydä laidunta. He kulkivat voimattomina vainoojan edessä.',
        7: 'Jerusalem muistelee kurjuutensa päivinä ja kärsimyksissään kaikkea kallisarvoista, mitä sillä oli entisinä päivinä. Kun sen kansa on sortunut vihollisen käsiin eikä sillä ole auttajaa, viholliset katselevat sitä ja nauravat sen sapateille.',
        8: 'Jerusalem on tehnyt syntiä synnin perään, sen tähden siitä on tullut saastaa. Kaikki, jotka sitä kunnioittivat, halveksivat sitä nyt, kun ovat nähneet sen alastomuuden. Itsekin se huokaa ja kääntyy pois.',
        9: 'Sen tahrat ovat sen liepeissä. Se ei ajatellut loppuaan, ja niin se sortui ihmeteltävästi. Sillä ei ole lohduttajaa. Katso, Herra, kurjuuttani, sillä vihollinen ylvästelee.',
        10: 'Vihollinen levitti kätensä kaikkia sen kalleuksia kohti. Niin, sen täytyi nähdä, kuinka pakanat tunkeutuivat sen pyhäkköön, ne, joita sinä olit kieltänyt tulemasta seurakuntaasi.',
        11: 'Kaikki sen kansa huokaa etsiessään leipää. Pysyäkseen hengissä he antavat ruuasta, mitä heillä on arvokasta. Katso, Herra, ja näe, kuinka halveksittu olen.',
        12: 'Eikö tämä koske teihin, kaikki ohikulkijat? Katsokaa ja nähkää: onko kipua, minun kipuni vertaista, joka on pantu kannettavakseni, jolla Herra on murehduttanut minut vihansa hehkun päivänä?',
        13: 'Hän lähetti tulen korkeudesta luihini ja kuritti niitä. Hän viritti verkon jalkojeni varalle, hän pani minut peräytymään, hän teki minut autioksi ja voimattomaksi kaiken päivää.',
        14: 'Hänen kätensä sitoi rikosteni ikeen. Ne kiedottiin yhteen, ja ne tulivat niskani päälle. Hän saattoi voimani kompastumaan. Herra antoi minut niiden käsiin, joista en voi nousta.',
        15: 'Herra hylkäsi kaikki vahvat miehet, joita keskuudessani oli. Hän kutsui kokoon juhlan minua vastaan murskatakseen nuorukaiseni. Herra polki viinikuurnan neitsyelle, tytär Juudalle.',
        16: 'Näitä minä itken, silmäni, silmäni vuotaa vettä, sillä kaukana on minusta lohduttaja, joka palauttaisi sieluni entiselleen. Hävitetyt ovat lapseni, sillä vihollinen on vahva.',
        17: 'Siion levittelee käsiään. Hänellä ei ole lohduttajaa. Herra on käskenyt Jaakobia vastaan sen viholliset joka taholta. Jerusalem on tullut saastaksi heidän keskellään.',
        18: 'Vanhurskas on hän, Herra. Sillä hänen sanaansa vastaan olen niskoitellut. Kuulkaa, te kansat kaikki, ja katsokaa kipuani. Neitsyeni ja nuorukaiseni ovat menneet vankeuteen.',
        19: 'Kutsuin niitä, jotka minua rakastivat. He hylkäsivät minut. Pappini ja vanhimpani ovat kuolleet kaupungissa etsiessään ruokaa pysyäkseen hengissä.',
        20: 'Katso, Herra, kuinka ahdistettu olen, sisukseni kuohuvat, sydämeni vääntyy rinnassani, sillä olen ollut hyvin uppiniskainen. Ulkona miekka ja sisällä kuolema on minua riistänyt.',
        21: 'He ovat kuulleet, kuinka minä huokailen. Minulla ei ole lohduttajaa. Kaikki vihamieheni ovat kuulleet onnettomuuteni. He iloitsevat, kun sinä olet tämän tehnyt. Sinä olet antanut tulla sen päivän, jonka olit ilmoittanut. Mutta käyköön heidän samoin kuin minun.',
        22: 'Tulkoon kaikki heidän pahuutensa sinun kasvojesi eteen, ja sälytä heille kannettavaksi se, minkä olet minulle pannut kaikkien rikoksieni tähden. Sillä monet ovat huokaukseni, ja sydämeni on voipunut.',
    },
    2: {
        1: 'Kuinka onkaan Herra vihallaan peittänyt tytär Siionin! Hän heitti taivaasta maahan Israelin kunnian eikä muistanut jalkojensa astinlautaa vihansa päivänä.',
        2: 'Herra on hävittänyt säälimättä kaikki Jaakobin asuinsijat. Hän on hajottanut vihassaan tytär Juudan linnoitukset ja hävittänyt ne maan tasalle. Hän on häväissyt valtakunnan ja sen ruhtinaat.',
        3: 'Hän on vihan hehkussa hakannut Israelin sarven kerrassaan poikki. Hän veti oikean kätensä takaisin vihamiehen edestä ja paloi Jaakobissa kuin tulenliekki, joka kuluttaa kaiken ympäriltään.',
        4: 'Hän jännitti jousensa kuin vihamies, seisoi oikea käsi koholla kuin vihollinen ja tappoi kaiken, mikä oli silmälle ihanaa. Tytär Siionin telttamajaan hän vuodatti kiivautensa kuin tulen.',
        5: 'Herra on ollut kuin vihamies ja on hävittänyt Israelin. Hän hävitti kaikki sen palatsit, turmeli sen linnoitukset ja tuotti tytär Juudalle paljon valitusta ja murhetta.',
        6: 'Hän särki aitauksensa kuin puutarhan aidan ja hävitti juhlanviettopaikkansa. Herra on saattanut unohduksiin Siionissa juhla-ajat ja sapatit ja on kiivaassa suuttumuksessaan saattanut häpeään kuninkaat ja papit.',
        7: 'Herra on hylännyt alttarinsa, häväissyt pyhäkkönsä, luovuttanut vihamiehen käteen palatsiensa muurit. He nostivat huudon Herran huoneessa, huudon kuin juhlapäivänä.',
        8: 'Herra oli päättänyt turmella tytär Siionin muurit. Hän on jännittänyt mittanuoran. Hän ei ole pidättänyt kättänsä hävittämästä ja on saattanut murheeseen varustukset ja muurit. Yhdessä ne menettävät voimansa.',
        9: 'Sen portit ovat vajonneet maahan. Hän särki ja mursi sen salvat. Sen kuningas ja ruhtinaat ovat pakanoiden seassa. Lakia ei ole, eivätkä sen profeetat saa näkyjä Herralta.',
        10: 'Maassa istuvat ääneti tytär Siionin vanhimmat. He ovat heittäneet tomua päänsä päälle ja vyöttäytyneet säkkeihin. Maata kohden ovat painaneet päänsä Jerusalemin neitsyet.',
        11: 'Silmäni ovat kyynelistä hiuenneet ja sisukseni kuohuvat. Maksani on maahan vuodatettu tyttären, kansani, sortumisen tähden. Sillä lapset ja imeväiset nääntyvät kaupungin kaduilla.',
        12: 'He sanovat äideilleen: "Missä on leipää ja viiniä?" kun he nääntyvät kuin kaatuneet kaupungin kaduilla ja heittävät henkensä äitiensä syliin.',
        13: 'Mitä sinulle mainitsisin, mihin vertaisin sinua, tytär Jerusalem? Minkä asettaisin rinnallesi lohduttaakseni sinua, neitsyt, tytär Siion? Sillä suuri kuin meri on sortumisesi. Kuka sinut parantaa?',
        14: 'Profeettasi ovat nähneet sinulle turhia, mauttomia näkyjä. He eivät ole paljastaneet syntiäsi, niin että olisivat kääntäneet kohtalosi, vaan ovat nähneet sinulle turhia, eksyttäviä ennustuksia.',
        15: 'Sinulle lyövät yhteen kämmeniään kaikki ohikulkijat, he viheltävät ja nyökyttävät ilkkuen päätään tytär Jerusalemille: "Tämäkö on kaupunki, jota sanottiin kauneuden täydellisyydeksi, kaiken maan iloksi?"',
        16: 'Suu ammollaan sinua vastaan ovat kaikki vihamiehesi. He viheltävät, kiristelevät hampaitaan ja sanovat: "Me olemme sen nielleet. Tämä on juuri se päivä, jota olemme toivoneet. Se on tullut meille, olemme sen nähneet."',
        17: 'Herra on tehnyt, mitä oli aikonut. Hän on täyttänyt sanansa, sen, josta hän oli antanut käskyn aikoja sitten. Hän on repinyt alas säälimättä, on antanut vihamiesten iloita sinusta ja kohottanut vihollistesi sarven. –',
        18: 'Heidän sydämensä voihkii Herran puoleen. Sinä, tytär Siionin muuri, anna kyyneltesi vuotaa virtana yötä päivää! Älä suo itsellesi lepoa, älköön silmäteräsi olko toimeton.',
        19: 'Nouse, kohota valitushuuto yöllä, kun yövartiot alkavat. Anna sydämesi vuotaa kuin vesi Herran kasvojen edessä. Kohota kätesi häntä kohden pienten lastesi elämän puolesta, kun ne nääntyvät nälkään kaikkien katujen kulmissa.',
        20: 'Katso, Herra, ja huomaa, ketä olet antanut tämän kohdata. Pitäisikö vaimojen syödä oma hedelmänsä, vaalimansa pienet lapset? Pitäisikö Herran pyhäkössä tappaa papit ja profeetat?',
        21: 'Maassa, kaduilla, makaa nuoria ja vanhoja. Neitsyeni ja nuorukaiseni ovat kaatuneet miekkaan. Sinä olet surmannut vihasi päivänä, olet teurastanut säälimättä.',
        22: 'Sinä kutsuit kuin juhlapäivän viettoon kauhistajani joka taholta. Herran vihan päivänä ei jäänyt pelastunutta eikä pakoon päässyttä. Ne, joita olin vaalinut ja jotka olin saanut isoiksi, ne minun vihamieheni lopetti.',
    },
    3: {
        1: 'Minä olen mies, joka olen nähnyt kurjuutta hänen vihastuksensa vitsan alla.',
        2: 'Hän on ajanut ja kuljettanut minut pimeyteen eikä valkeuteen.',
        3: 'Juuri minua vastaan hän on kääntänyt kätensä kaiken päivää.',
        4: 'Hän on kalvanut lihani ja nahkani ja musertanut luuni.',
        5: 'Hän on rakentanut varustukset minua vastaan ja piirittänyt minut myrkyllä ja vaivalla.',
        6: 'Hän on pannut minut asumaan pimeydessä kuin entisajan kuolleet.',
        7: 'Hän on tehnyt muurin ympärilleni, niin etten pääse ulos. Hän on pannut minut raskaisiin vaskikahleisiin.',
        8: 'Vaikka itken ja huudan apua, hän vaientaa rukoukseni.',
        9: 'Hakatuista kivistä hän on tehnyt teilleni muurin ja mutkistanut polkuni.',
        10: 'Vaaniva karhu hän on ollut minulle, piilossa väijyvä leijona.',
        11: 'Hän on vienyt harhaan tieni, repinyt minut kappaleiksi ja tehnyt minut autioksi.',
        12: 'Hän on jännittänyt jousensa ja asettanut minut nuoltensa maalitauluksi.',
        13: 'Hän on ampunut munuaisiini viinensä lapset.',
        14: 'Minusta on tullut koko kansalleni naurun ja heidän jokapäiväisen pilkkalaulunsa aihe.',
        15: 'Hän on ravinnut minua katkeruudella, juottanut minua koiruoholla.',
        16: 'Hän on murskannut hampaani soralla painaessaan minut alas tomuun.',
        17: 'Sinä olet syössyt sieluni pois rauhasta, olen unohtanut, mitä on onni.',
        18: 'Sanon: mennyt on voimani ja toivoni Herraan.',
        19: 'Muista, kuinka kurja ja hylätty olen, minulle on juotettu koiruohoa ja myrkkyä.',
        20: 'Sitä muistellessani sieluni vajoaa alas.',
        21: 'Tämän panen sydämelleni, sen tähden odotan.',
        22: 'Herran armoa on, ettemme ole aivan hävinneet, sillä hänen laupeutensa ei ole loppunut:',
        23: 'se on joka aamu uusi, ja suuri on hänen uskollisuutensa.',
        24: 'Minun osani on Herra, sanoo sieluni. Sen tähden odotan häntä.',
        25: 'Hyvä on Herra häntä odottaville, sielulle, joka häntä etsii.',
        26: 'Hyvä on hiljaisuudessa toivoa Herran apua.',
        27: 'Hyvä on miehelle, että hän kantaa iestä nuoruudessaan.',
        28: 'Istukoon hän yksin ja hiljaa, kun Herra on pannut sen hänen päällensä.',
        29: 'Laskekoon suunsa tomuun – ehkä on toivoa.',
        30: 'Ojentakoon hän posken sille, joka häntä lyö, saakoon häväistystä kylliksi.',
        31: 'Sillä Herra ei hylkää iankaikkisesti,',
        32: 'vaan jos hän on saattanut murheelliseksi, hän osoittaa laupeutta suuressa armossaan.',
        33: 'Sillä hän ei vaivaa sydämensä halusta eikä murehduta ihmislapsia.',
        34: 'Kun jalkojen alle murskataan kaikki vangit maassa,',
        35: 'kun väännetään miehen oikeus Korkeimman kasvojen edessä,',
        36: 'kun ihmiselle tehdään vääryyttä hänen riita-asiassaan – eikö Herra näkisi sitä?',
        37: 'Onko kukaan sanonut, ja se on tapahtunut, mitä Herra ei ole käskenyt?',
        38: 'Korkeimman suusta lähtee paha ja hyvä.',
        39: 'Miksi tuskittelee ihminen eläessään, tuskitelkoon mies syntiensä tähden?',
        40: 'Koetelkaamme teitämme, tutkikaamme niitä ja palatkaamme Herran luo.',
        41: 'Kohottakaamme sydämemme ja kätemme Jumalan puoleen, joka on taivaassa.',
        42: 'Me olimme luopuneet pois ja olleet kapinalliset. Sinä et ole antanut anteeksi.',
        43: 'Sinä peitit itsesi vihaan, ajoit meitä takaa, surmasit etkä säälinyt.',
        44: 'Sinä olet peittänyt itsesi pilvellä, niin ettei rukous pääse läpi.',
        45: 'Tunkioksi ja hylkytavaraksi sinä olet meidät tehnyt kansakuntien joukossa.',
        46: 'Kaikki vihamiehemme ovat avanneet suunsa meitä vastaan.',
        47: 'Osaksemme ovat tulleet kauhu ja kuoppa, autius ja hävitys.',
        48: 'Vesipurot juoksevat silmistäni tyttären, kansani, sortumisen tähden.',
        49: 'Silmäni vuotaa lakkaamatta, taukoamatta,',
        50: 'kunnes Herra katsoo ja näkee taivaasta.',
        51: 'Silmäni tuottaa tuskaa sielulleni kaikkien kaupunkini tyttärien tähden.',
        52: 'Kiihkeästi pyydystivät minua kuin lintua ne, jotka ovat syyttä vihamiehiäni.',
        53: 'He sulkivat kuoppaan elämäni ja heittivät päälleni kiviä.',
        54: 'Vedet tulvivat pääni yli. Sanoin: olen hukassa.',
        55: 'Minä huusin, Herra, syvältä kaivosta nimeäsi.',
        56: 'Kuulit huutoni. Älä peitä korvaasi huudoltani äläkä huokaukseltani.',
        57: 'Olit läsnä silloin, kun sinua huusin. Sanoit: "Älä pelkää."',
        58: 'Sinä, Herra, ajoit sieluni asian ja lunastit henkeni.',
        59: 'Olethan nähnyt, Herra, kärsimäni sorron: hanki minulle oikeus.',
        60: 'Olethan nähnyt kaiken heidän kostonsa ja kaikki heidän juonensa minua vastaan.',
        61: 'Olet kuullut heidän häväistyksensä, Herra ja kaikki heidän juonensa minua vastaan.',
        62: 'Minun vastustajieni huulet ja heidän aikeensa ovat minua vastaan kaiken päivää.',
        63: 'Istuivatpa he tai nousivat, katso: minä olen heille pilkkalauluna.',
        64: 'Kosta heille, Herra, heidän kättensä teot.',
        65: 'Anna heille pelko sydämeen, ja kohdatkoon heitä kirouksesi.',
        66: 'Aja heitä takaa vihassasi ja hävitä heidät Herran taivaan alta.',
    },
    4: {
        1: 'Kuinka onkaan kulta tummunut, muuttunut hyvä kulta. Kuinka pyhät kivet on viskelty kaikkiin kadunkulmiin!',
        2: 'Siionin pojat, nuo kalliit, punnitut puhtaimman kullan arvoisiksi – kuinka he ovatkaan saviastioiden, savenvalajan kätten tekojen, arvoisia!',
        3: 'Valaatkin tarjoavat nisiään ja imettävät poikasiaan, mutta tytär, minun kansani, on tullut tylyksi kuin strutsi erämaassa.',
        4: 'Imeväisen kieli tarttuu suulakeen janon tähden. Lapsukaiset pyytävät leipää, eikä ole, kuka sitä heille taittaisi.',
        5: 'Ne, jotka söivät herkkuja, nääntyvät kaduilla. Ne, joita purppuran päällä kanneltiin, syleilevät tunkioita.',
        6: 'Tyttären, kansani, syntivelka on Sodoman syntiä suurempi. Sodoma hävitettiin äkkiä käsien koskematta.',
        7: 'Sen nasiirit olivat lunta puhtaammat ja maitoa valkoisemmat, heidän hahmonsa oli koralleja punaisempi ja he olivat näöltään kuin safiiri.',
        8: 'Nyt heidän muotonsa on nokea mustempi, eikä heitä tunneta kaduilla. Heidän nahkansa on kiinni luissa ja on kuivettunut kuin puu.',
        9: 'Parempi oli miekan kaatamien kuin nälän kaatamien, jotka menehtyivät kuin lävistetyt, pellon viljaa vailla.',
        10: 'Armeliaat vaimot keittivät omin käsin lapsiaan. Ne tulivat heille ruuaksi tyttären, kansani, sortuessa.',
        11: 'Herra on pannut täytäntöön kiivautensa, vuodattanut vihansa hehkun. Hän on sytyttänyt Siioniin tulen, joka on kuluttanut sen perustukset.',
        12: 'Eivät olisi uskoneet maan kuninkaat, eikä kukaan maanpiirin asukkaista, että vastustaja ja vihollinen hyökkää sisään Jerusalemin porteista.',
        13: 'Se tapahtui profeettojen syntien ja sen pappien pahojen tekojen tähden, niiden, jotka siellä olivat vuodattaneet vanhurskaiden verta.',
        14: 'He harhailivat sokeina kaduilla, verellä tahrattuina, niin ettei heidän vaatteisiinsa voinut koskea.',
        15: '"Väistykää! Saastainen!" huudettiin heistä. "Väistykää, väistykää, älkää koskeko!" He pakenivat ja kulkivat. Pakanoiden seassa sanottiin: "He eivät saa enää asua täällä."',
        16: 'Herran kasvot ovat hajottaneet heidät, eikä hän heihin enää katso. Pappeja ei kunnioitettu eikä vanhimpia armahdettu.',
        17: 'Vieläkin odotimme silmät rauenneina turhaan apua. Tähystyspaikastamme tähyilimme kansaa, josta ei tullut pelastusta.',
        18: 'Askeleitamme vaanittiin, niin ettemme voineet kulkea kaduillamme. Meidän loppumme lähestyi, päivämme täyttyivät – niin, loppumme tuli.',
        19: 'Vainoojamme olivat nopeammat kuin kotkat taivaalla. Vuorilla he ajoivat meitä takaa ja väijyivät meitä erämaassa.',
        20: 'Hän, elämämme turva, Herran voideltu, joutui vangiksi heidän kuoppiinsa, hän, josta me olimme sanoneet: hänen varjossaan elämme pakanakansojen joukossa.',
        21: 'Iloitse ja riemuitse, tytär Edom, joka asut Uusin maassa! Mutta malja on tuleva sinunkin kohdallesi: sinä juovut ja paljastat itsesi.',
        22: 'Sinun syntivelkasi, tytär Siion, on loppunut, eikä Herra enää siirrä sinua vankeuteen. Sinun syntivelkasi, tytär Edom, hän on kostava ja paljastava syntisi.',
    },
    5: {
        1: 'Muista, Herra, mitä meille on tapahtunut. Katso ja näe häväistyksemme.',
        2: 'Perintöosamme on siirtynyt vieraille ja talomme muukalaisille.',
        3: 'Olemme tulleet orvoiksi, isättömiksi, äitimme ovat kuin leskiä.',
        4: 'Oman juomavetemme ostamme rahalla. Saamme omat puumme, jos maksamme niistä hinnan.',
        5: 'Vainoojamme ovat niskassamme. Kun uuvumme, meille ei ole lepoa.',
        6: 'Egyptille ja Assurille olemme lyöneet kättä saadaksemme tarpeeksi leipää ravinnoksi.',
        7: 'Isämme ovat syntiä tehneet. Heitä ei enää ole. Me kannamme heidän syntiensä taakkaa.',
        8: 'Orjat hallitsevat meitä. Ei ole sitä, joka tempaisi meidät heidän käsistään.',
        9: 'Henkemme kaupalla noudamme leipämme väistäen miekkaa erämaassa.',
        10: 'Ihomme oli musta kuin uuni nälän poltteiden takia.',
        11: 'Naisia raiskataan Siionissa, neitsyitä Juudan kaupungeissa.',
        12: 'Ruhtinaita heidän kätensä hirttävät, vanhinten kasvoja ei pidetä arvossa.',
        13: 'Nuorukaiset kantavat myllynkiviä, poikaset kompastelevat puutaakkojen alla.',
        14: 'Poissa ovat vanhukset porteista, nuorukaiset soittimiensa äärestä.',
        15: 'Poissa on ilo sydämistämme, karkelomme on muuttunut valitukseksi.',
        16: 'Pudonnut on päästämme kruunu. Voi meitä, sillä olemme syntiä tehneet!',
        17: 'Tästä syystä on sydämemme tullut sairaaksi, näiden tähden ovat silmämme pimenneet –',
        18: 'Siionin vuoren tähden, joka on autiona, jolla ketut juoksentelevat.',
        19: 'Sinä, Herra, pysyt iankaikkisesti ja valtaistuimesi polvesta polveen.',
        20: 'Miksi unohdat meidät ainiaaksi, hylkäät meidät pitkiksi ajoiksi?',
        21: 'Palauta meidät, Herra, luoksesi, niin palaamme. Uudista päivämme entiselleen.',
        22: 'Vai oletko meidät kokonaan hylännyt ja vihastunut meihin yli määrän?',
    },
}
